<script setup lang="ts">
import type { WorkspaceDetail } from '../../../types/api'
definePageMeta({ middleware: 'workspace' })
const route = useRoute(); const api = useApi(); const workspace = ref<WorkspaceDetail>(); const error = ref('')
onMounted(async () => { try { workspace.value = await api.get(`/workspaces/${encodeURIComponent(String(route.params.workspaceId))}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Workspace unavailable.' } })
</script>
<template><section class="page-sheet"><p v-if="error" class="notice notice--error">{{ error }}</p><template v-else-if="workspace"><header class="page-header"><div><p class="eyebrow">Workspace overview</p><h1>{{ workspace.name }}</h1><code>{{ workspace.root }}</code></div><span class="status-lozenge">{{ workspace.available ? 'Operational' : 'Unavailable' }}</span></header><p v-if="workspace.problem" class="notice notice--error">{{ workspace.problem }}</p><div class="metric-grid"><NuxtLink :to="`/workspaces/${workspace.id}/sites`"><strong>{{ workspace.sites.length }}</strong><span>Sites</span></NuxtLink><NuxtLink :to="`/workspaces/${workspace.id}/layers`"><strong>{{ workspace.layers.length }}</strong><span>Layers</span></NuxtLink><NuxtLink :to="`/workspaces/${workspace.id}/config`"><strong>{{ workspace.warnings.length }}</strong><span>Warnings</span></NuxtLink></div><section v-if="workspace.warnings.length" class="panel"><p class="eyebrow">Inspection notes</p><ul><li v-for="warning in workspace.warnings" :key="warning.code"><strong>{{ warning.code }}</strong> — {{ warning.message }}</li></ul></section></template><p v-else class="empty-state">Inspecting workspace…</p></section></template>
